import{_ as a,C as s,o as n,c as i,a3 as l,E as d,w as c,j as t,a as e}from"./chunks/framework.DKrWOZ-k.js";const g="/versions/v0.19.96/screens/routing/virtual_a_out.png",u="/versions/v0.19.96/screens/routing/virtual_a_in.png",S=JSON.parse('{"title":"Routing","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/routing.md","filePath":"concepts/routing.md"}'),h={name:"concepts/routing.md"};function p(I,r,m,T,D,_){const o=s("ManualRelated");return n(),i("div",null,[r[1]||(r[1]=l('<h1 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h1><p>The S32 sends and receives MIDI on its ports, and on four virtual ports that connect racks inside a project.</p><h2 id="physical-ports" tabindex="-1">Physical ports <a class="header-anchor" href="#physical-ports" aria-label="Permalink to &quot;Physical ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>USB</strong></td><td>A computer or tablet (MIDI in and out)</td></tr><tr><td><strong>MIDI IN</strong>, <strong>MIDI OUT 1</strong>, <strong>MIDI OUT 2</strong></td><td>Hardware synths and drum machines (TRS + included DIN adapters)</td></tr><tr><td><strong>MIDI THRU</strong></td><td>A copy of whatever arrives at <strong>MIDI IN</strong></td></tr><tr><td><strong>USB HOST</strong></td><td>USB MIDI keyboard or controller plugged into the S32, or several through a powered hub</td></tr></tbody></table><h2 id="virtual-midi-a–d" tabindex="-1">Virtual MIDI A–D <a class="header-anchor" href="#virtual-midi-a–d" aria-label="Permalink to &quot;Virtual MIDI A–D&quot;">​</a></h2><p><strong>Virtual ports</strong> are internal cables between racks in the same project.</p><ol><li>Add <strong>MIDI OUT</strong> at the end of rack 1.</li><li>Set <strong>PORT</strong> to <strong>VIRTUAL A</strong> (or B, C, D).</li><li>In rack 2, add <strong>MIDI IN</strong>.</li><li>Set its <strong>PORT</strong> to <strong>VIRTUAL A</strong>.</li></ol><p>Use it to feed one rack&#39;s output into another, for example an arpeggiator in rack 1 driving a scaler in rack 2. Nothing reaches a real port unless a <strong>MIDI OUT</strong> sends it there.</p><p><img src="'+g+'" alt="Rack 01 MIDI OUT: PORT set to VIRTUAL A" class="screen"></p><p><img src="'+u+'" alt="Rack 02 MIDI IN: PORT set to VIRTUAL A" class="screen"></p><h2 id="usb-host" tabindex="-1">USB Host <a class="header-anchor" href="#usb-host" aria-label="Permalink to &quot;USB Host&quot;">​</a></h2><p>Choose <strong>USB HOST</strong> as the <strong>PORT</strong> to play a USB-only synth plugged into the rear <strong>HOST</strong> port. With a powered hub, several devices share the port: they all play into the S32, and <strong>USB HOST</strong> output reaches all of them.</p><h2 id="midi-out" tabindex="-1">MIDI Out <a class="header-anchor" href="#midi-out" aria-label="Permalink to &quot;MIDI Out&quot;">​</a></h2><p>Every chain that should produce MIDI ends with a <strong>MIDI OUT</strong> device. Its <strong>PORT</strong> parameter picks:</p><ul><li><strong>USB</strong></li><li><strong>MIDI1</strong></li><li><strong>MIDI2</strong></li><li><strong>USB HOST</strong></li><li><strong>VIRTUAL A</strong>, <strong>B</strong>, <strong>C</strong>, <strong>D</strong></li></ul>',15)),d(o,null,{default:c(()=>[...r[0]||(r[0]=[t("ul",null,[t("li",null,[t("a",{href:"./../racks/#rack-limits"},"Rack limits"),e(" — How many devices fit in a rack")]),t("li",null,[t("a",{href:"./../devices/midi-output"},"MIDI Out device"),e(" — Port selection per rack")]),t("li",null,[t("a",{href:"./../devices/"},"Device reference"),e(" — Every MIDI device type")])],-1)])]),_:1})])}const f=a(h,[["render",p]]);export{S as __pageData,f as default};
